// Devuelve el comprobante como imagen
const f = String(($input.first().json || {}).foto || '');
if (!f) return [{ json: { falta: true } }];
return [{ json: { falta: false }, binary: { data: { data: f, mimeType: 'image/jpeg', fileName: 'comprobante.jpg', fileExtension: 'jpg' } } }];

// ¿Qué disparó el flujo? (avisos de cada hora o resumen del día) y revisa que el bot esté configurado
const cfg = $input.first().json;
const corrio = n => { try { return $(n).isExecuted; } catch (e) { return false; } };
const chats = String(cfg.chat_ids || '').split(/[,\s]+/).filter(x => /^-?\d+$/.test(x));
if (!/^\d+:/.test(String(cfg.telegram_token || '')) || !chats.length)
  throw new Error('Pon el token del bot y al menos un chat en "Configuración del bot".');
return [{ json: { origen: corrio('Cada hora') ? 'avisos' : 'resumen', chats } }];

// Un solo mensaje con lo que pasó la hora límite y sigue mal (🔴 o 🟠), a cada chat configurado. Se registra todo en la web.
const chats = $('Origen').first().json.chats;
let r = $input.first().json.r || {}; if (typeof r === 'string') r = JSON.parse(r);
const A = r.avisos || [];
if (!A.length) return [];
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const $$ = n => '$' + Number(Math.abs(n || 0)).toLocaleString('es-MX', { maximumFractionDigits: 2 });
const falta = a => {
  if (a.clase === 'retiro') return 'reportarlo + ticket';
  if (a.clase === 'cobro') return String(a.motivo).replace(/^FALTA /, '').toLowerCase();
  if (a.clase === 'compra') return 'comprobante de la compra';
  if (/FALTA COMPROBANTE/.test(a.motivo)) return a.tipo === 'compra' ? 'ticket + recepción de compra en Microsip' : 'ticket';
  if (/FALTA RECEPCI/.test(a.motivo)) return 'recepción de compra en Microsip';
  return a.motivo;
};
const L = A.slice(0, 20).map(a => `${a.estado === 'rojo' ? '🔴' : '🟠'} <b>${esc(a.folio)}</b> · ${$$(a.importe)} · ${esc(a.empleado || '?')}` +
  (a.pedido ? `\nPedido ${esc(a.pedido)}` : '') + `\n${esc(String(a.concepto).slice(0, 90))}` +
  `\nFalta: ${esc(falta(a))}${a.horas > 0 ? ' · ' + a.horas + ' h' : ''}`);
const text = `⚠️ <b>Comprobación pendiente</b>${A.length > 1 ? ' (' + A.length + ')' : ''}\n\n` + L.join('\n\n') +
  (A.length > 20 ? `\n\n…y ${A.length - 20} más.` : '') + '\n\nSe completa en Mis ligas → 🧾 Auditoría de movimientos.';
const claves = A.map(a => a.clave);
return chats.map(chat_id => ({ json: { chat_id, text: text.slice(0, 4000), claves } }));

// Resumen del día al cierre, a cada chat configurado
const chats = $('Origen').first().json.chats;
let r = $input.first().json.r; if (typeof r === 'string') r = JSON.parse(r);
if (!r || !r.ok) throw new Error('No se pudo leer el resumen: ' + JSON.stringify($input.first().json.error || r).slice(0, 300));
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const $$ = n => '$' + Math.round(Number(n || 0)).toLocaleString('es-MX');
const EMO = { verde: '🟢', naranja: '🟠', rojo: '🔴', pendiente: '⏳' };
const s = r.resumen, P = r.lista.filter(x => x.estado === 'rojo' || x.estado === 'naranja');
const f = r.desde;
const text = `📊 <b>AUDITORÍA — ${f.slice(8, 10)}/${f.slice(5, 7)}</b>\n\n` +
  `🟢 ${s.verde} movimientos cuadrados\n🟠 ${s.naranja} por revisar\n🔴 ${s.rojo} inconsistencias\n💰 <b>${$$(s.sin_comprobar)}</b> sin comprobar` +
  (r.atrasados.n ? `\n⚠️ ${r.atrasados.n} de días anteriores sin resolver (${$$(r.atrasados.monto)})` : '') +
  (P.length ? '\n\n' + P.slice(0, 12).map(x => `${EMO[x.estado]} ${esc(x.folio)} · ${$$(x.importe)} · ${esc(x.empleado || '?')} — ${esc(x.motivo)}`).join('\n') + (P.length > 12 ? `\n…y ${P.length - 12} más.` : '')
    : '\n\n✅ Todo comprobado.');
return chats.map(chat_id => ({ json: { chat_id, text: text.slice(0, 4000) } }));

