// Ligas de la auditoría. Los empleados se dan de alta desde la página (Empleados) con la liga de administrador.
const cfg = $('Configuración (ligas)').first().json, a = $('Ligas').first().json;
const url = String(cfg.url_n8n || '').replace(/\/+$/, '') + '/webhook/auditoria-mov?k=';
let E = a.empleados; if (typeof E === 'string') E = JSON.parse(E);
const out = { administrador: url + a.t_admin, auditora: url + a.t_aud };
for (const e of E || []) out['empleado ' + e.nombre] = url + e.token;
return [{ json: out }];
